# aeneid-044 draft. Drafted from the Latin and grammar only. t is cut from the edition, never typed.
TITLE = 'Cerberus. Lugentes campi. Dido. Deiphobus'
TITLE_EN = "The Crossing, Dido and Deiphobus — Aeneid VI.398–508"
PART = "The Crossing, Dido and Deiphobus (VI.398–508)"
ABOUT = """The Sibyl answers Charon: they have come with no treachery and offer no violence; Aeneas of Troy, famous for his devotion and his deeds of arms, is going down to see his father, and if that does not move the ferryman, this bough will. She uncovers the golden bough, and Charon's anger falls away at once. He turns his boat to the bank, clears out the shades sitting on the benches and takes Aeneas aboard; the stitched boat groans under a living man's weight and lets in the marsh-water, but sets them down safe in the mud on the far side. There Cerberus, the three-throated watchdog, lies in his cave; the Sibyl throws him a cake soaked in honey and drugs, he gulps it down and sprawls asleep, and Aeneas slips past. The first regions they come to hold those who died before their time: the wailing souls of infants, men condemned to death on false charges, whose places are allotted by Minos sitting as judge, and the suicides, who would now gladly bear poverty and hard labour in the world above, but are held in by the nine coils of the Styx. Next come the Fields of Mourning, where myrtle groves hide those whom love destroyed, Phaedra, Procris, Eriphyle, Evadne, Pasiphaë, Laodamia and Caeneus. Among them, her wound still fresh, wanders Dido. Aeneas makes her out dimly, like a new moon through clouds, and weeps: he swears he left her shore against his will, driven by the gods' commands, and never believed his going would grieve her so. She keeps her eyes on the ground, as unmoved as marble, and at last turns away into the grove where her first husband Sychaeus returns her love, while Aeneas follows her with his tears. Then they reach the farthest fields, where the famous warriors dwell: heroes of the war against Thebes, and the Trojan dead, who throng round Aeneas and cannot have enough of him, while the Greek dead flee in panic or raise thin cries that die in their throats. Last Aeneas sees Deiphobus, son of Priam, his face, hands, ears and nose hacked and mutilated, and hardly knows him. He asks who could have done such cruelty, and tells him that he heard he had fallen on the last night of Troy, and that he raised him an empty tomb on the Trojan shore, but could not find his body to bury."""
U = [
(398, 'vates:',
 """To which in reply briefly spoke the Amphrysian seer:""",
 """To this the Amphrysian prophetess gave a brief reply:""",
 """A new paragraph. 'Quae' is a connecting relative, 'these things', and 'contra', set after it, is 'in answer to': she is replying to Charon's challenge (388–397). 'Fata est' is the perfect of the deponent 'for', 'speak', as at 321. 'Amphrysia vates' is 'the Amphrysian seer'. The Amphrysus is a river in Thessaly beside which Apollo, banished from heaven for a year, kept the flocks of King Admetus; 'Amphrysian' therefore means 'Apollo's', a learned, roundabout epithet of the kind Alexandrian poets liked, for the Sibyl is his priestess. The colon opens her answer."""),
(399, 'moveri;',
 """“No such plots are here; cease to be troubled;""",
 """“There is no trickery of that kind here; put away your alarm;""",
 """The opening mark begins the Sibyl's speech, which runs to 407. The verb is left out: 'nullae hic insidiae tales (sunt)', 'there are no such plots here'. 'Insidiae', always plural, is 'ambush', 'treachery', and 'tales' points back to Charon's fear that this armed man has come, like Theseus and Pirithous, to carry someone off. 'Absiste moveri' is 'leave off being disturbed', 'absisto' with the infinitive, a construction of verse."""),
(400, 'ferunt;',
 """nor violence do the weapons bring;""",
 """these weapons threaten no violence;""",
 """'Tela' are Aeneas's arms, the sword he drew at the Sibyl's bidding (260, 290), which made Charon call him 'armatus' (388). 'Vim ferre' is 'to bring force', 'to offer violence'."""),
(402, 'limen.',
 """let the huge doorkeeper in his cave,
eternally barking, the bloodless terrify shades,
chaste let her uncle's keep Proserpina threshold.""",
 """the giant gatekeeper may bark in his cave for ever and frighten the bloodless shades, and Proserpina may stay chaste and keep to her uncle's house.""",
 """'Licet' with the subjunctive, twice ('terreat', 'servet'), is 'it is allowed that', 'for all we care, let…': the Sibyl concedes that the order of the underworld will stand untouched. 'Ingens ianitor' is Cerberus, whom they meet at 417; 'antro' is an ablative of place. 'Aeternum' is an adverbial accusative, 'for ever'. 'Exsanguis… umbras' wraps round the verb, 'the bloodless shades', with the '-is' accusative plural: in Odyssey 11 the dead must drink blood before they can speak. 'Patrui' is 'of her father's brother': Proserpina, daughter of Jupiter and Ceres, was carried off by Dis, Jupiter's brother, so her husband is also her uncle. 'Casta' answers Charon's last words (397): Aeneas has not come to carry off the queen. 'Limen', 'threshold', is the house itself."""),
(404, 'umbras.',
 """Trojan Aeneas, for devotion distinguished and for arms,
to his father, to the lowest of Erebus goes down, to the shades.""",
 """Aeneas of Troy, famed for his devotion and for his feats of arms, is going down to his father among the deepest shades of Erebus.""",
 """The Sibyl names him with his credentials, as a herald would. 'Pietate… et armis' are ablatives of respect with 'insignis', 'distinguished in'. 'Pietas' is Aeneas's defining virtue, duty to the gods, to his father and to his people, and here it explains the journey, made to see his father. 'Ad… ad' doubles the preposition, first the person, then the place. Erebus is the darkness under the earth, here the underworld itself; 'imas' is 'lowest'. 'Descendit' is present, 'is going down'. 'Troius' has three syllables, Tro-i-us."""),
(407, 'adgnoscas.',
 """If you not at all moves the image of such great devotion,
yet this bough” (she uncovers the bough, which in her robe lay hidden)
“you will recognise.”""",
 """If the sight of devotion so great does not move you at all, this bough at least” — she uncovers the bough that lay hidden in her robe — “you will know.”""",
 """The print has 'hunc ”(aperit' and 'adgnoscas. ”Tumida', a misprint for 'hunc” (aperit' and 'adgnoscas.” Tumida', corrected here: both closing marks are set after a space and joined to what follows. t keeps the print, with the second mark standing at the head of the next unit, while l and i close the speech after 'adgnoscas.'. 'Nulla' is used as an adverb, 'not at all'. 'Imago' is 'picture', 'sight': the spectacle of such pietas. 'At' after a 'si' clause is 'yet at least'. The parenthesis breaks into the speech with the gesture: 'aperit' is 'uncovers', and 'veste' is an ablative of place, 'in her robe'. 'Adgnoscas' is Greenough's spelling of 'agnoscas' (the Latin Library's), a subjunctive of mild command or of confident expectation, 'you will surely recognise'. The golden bough, which Aeneas plucked on the Sibyl's instructions (136–148, 210–211) as a gift for Proserpina, is the living man's passport below."""),
(407, 'residunt.',
 """Swollen with anger then his heart settles.""",
 """At that the anger that swelled his heart subsided.""",
 """The print has 'adgnoscas. ”Tumida', a misprint for 'adgnoscas.” Tumida', corrected here; the mark at the head of t belongs to the Sibyl's speech just ended, so l and i carry none. 'Tumida ex ira' is 'swollen from anger', 'ex' giving the cause. 'Corda' is a poetic plural for Charon's one heart. 'Residunt' is 'settle down', 'subside', the word for a swell of water going down."""),
(408, 'his.',
 """Nor more than these.""",
 """No more was said.""",
 """The verb of speaking is left out, as so often: 'nec plura (dicta sunt)'. 'His' is an ablative of comparison, 'more than these (words)'. Charon's silence makes its own point: the bough is answer enough."""),
(410, 'propinquat.',
 """He, marvelling at the venerable gift
of the fateful wand, after a long time seen,
his dark stern turns round, and to the bank draws near.""",
 """Gazing in wonder at the hallowed offering, the bough of destiny, seen again after so long, he turned his dusky stern about and came in close to the bank.""",
 """'Ille' is Charon. 'Venerabile donum / fatalis virgae' is 'the awesome gift of the fated wand', a genitive of definition: the gift is the branch, meant for Proserpina, and 'fatalis' is 'appointed by fate'. 'Longo post tempore visum' is 'seen after a long time': 'post' is an adverb, 'longo tempore' an ablative of the measure of difference. No living man has come this way with a bough for many years. 'Caeruleam' is 'dark', 'sea-coloured', a colour of the sea and of death. 'Advertit puppim' is 'turns his stern towards' them, for he had pushed off. 'Ripae' is a dative with 'propinquat', 'draws near to the bank'."""),
(412, 'foros;',
 """Then the other souls, who along the long benches were sitting,
he tumbles out, and clears the gangways;""",
 """Then he turned out the other souls, who sat along the rows of thwarts, and cleared the gangways;""",
 """'Iuga', 'yokes', are the rowing benches, which cross the boat as a yoke crosses a pair of oxen. 'Deturbat' is 'knocks off', 'thrusts out', a rough word for rough handling. 'Foros' are the gangways or decking ('fori' are also the rows of seats in the Circus), and 'laxat' is 'makes room in'. The present tenses are historic presents, carrying the story along."""),
(413, 'Aenean.',
 """at once he takes into the hull
huge Aeneas.""",
 """and at the same moment he took the mighty Aeneas into the hold.""",
 """'Alveo' is 'in the hollow', the hull, an ablative of place, scanned as two syllables (alv-yo) by synizesis. 'Aenean' is a Greek accusative. 'Ingentem' is more than praise: heroes are larger than men now, and he is a living body with weight, as the next sentence shows."""),
(414, 'paludem.',
 """Groaned under the weight the boat
stitched, and much took in, leaky, of the marsh.""",
 """The stitched boat groaned under the weight, and its seams let in a great deal of the marsh.""",
 """'Cymba… sutilis' is 'the sewn boat', made of hides or planks stitched together, as the oldest boats were; Greenough spells 'cymba', the Latin Library 'cumba', as at 303. 'Gemuit' is a perfect among historic presents: the instant of the groan. The shades weigh nothing, so the first living passenger strains the boat; in the Iliad (5.838–839) the oak axle of Diomedes' chariot groans under the weight of Athena when she mounts beside him. 'Rimosa' is 'full of cracks', predicative, 'leaky as it was'. 'Multam… paludem' is 'much marsh-water'."""),
(416, 'ulva.',
 """At last across the river, unharmed, both seer and man
on shapeless mud and grey-green he lands, in the sedge.""",
 """At last he set the priestess and the hero down unharmed across the river, on the formless slime among the grey-green sedge.""",
 """'Vatemque virumque' is the double '-que', 'both the seer and the man'. 'Incolumis' is an accusative plural in '-is', with both. 'Informi limo' is 'on the shapeless mud', an ablative of place, and 'glauca… in ulva' is 'in the grey-green sedge', with the preposition set between adjective and noun; 'glaucaque' elides before 'exponit'. 'Exponit' is the word for putting passengers ashore."""),
(418, 'antro.',
 """Cerberus these, huge, with barking realms three-throated
makes resound, opposite lying, monstrous, in a cave.""",
 """Huge Cerberus fills this realm with the din of his three-throated barking, sprawled enormous in a cave facing them.""",
 """A new paragraph. 'Personat' is 'makes resound', here transitive with 'haec… regna'. 'Latratu… trifauci' is 'with three-throated barking', an ablative of means; 'trifaux' is a word coined for him. Cerberus is the hound of the underworld: Homer calls him only 'the dog of Hades' (Iliad 8.368; Odyssey 11.623), Hesiod gives him fifty heads (Theogony 311–312), later tradition three. 'Adverso… in antro' is 'in a cave facing them', across their path. 'Recubans' is 'lying back', 'sprawling'. Hercules dragged him off to the upper world (396)."""),
(421, 'obicit.',
 """To whom the seer, seeing bristling now his necks with snakes,
with honey drugged and medicated grain a lump
throws.""",
 """The priestess, seeing the snakes already rising on his necks, threw him a lump of meal steeped in sleepy honey and drugs.""",
 """'Cui' is a connecting relative, 'to him', the dative with 'obicit'. 'Horrere… colla colubris' is an accusative and infinitive after 'videns', 'that his necks were bristling with snakes': as he wakes to them, the serpents on his necks rise. 'Melle soporatam' is 'made sleepy with honey', honey laced with a sleeping-drug; 'medicatis frugibus' is 'drugged grain'. 'Offa' is a lump or cake of meal. The verb 'obicit' is held back to the start of the next line. 'A sop to Cerberus' became a proverb from this passage."""),
(423, 'antro.',
 """He, with hunger ravening his three throats opening,
snatches it thrown, and his monstrous back relaxes,
sprawled on the ground, and over the whole huge is stretched cave.""",
 """Opening his three throats in a frenzy of hunger he snatched what was thrown, then let his monstrous back go slack, sprawled on the ground, and lay stretched out huge across the whole cave.""",
 """'Fame rabida' is an ablative of cause, 'with raging hunger'. 'Obiectam' (offam) picks up 'obicit': 'it, as it was thrown'. 'Terga' is a poetic plural, and 'resolvit' is 'loosens', the word for limbs going slack in sleep; 'corripit obiectam, atque' elides. 'Fusus humi' is 'spread on the ground', 'humi' a locative. 'Toto… antro' is an ablative of place, 'over the whole cave', and 'ingens' is predicative: he lies there, huge."""),
(425, 'undae.',
 """Seizes Aeneas the entrance, the guard buried,
and gets clear, swift, of the bank of the unreturning wave.""",
 """With the guard buried in sleep Aeneas took the entrance, and was quickly past the bank of the water that none crosses twice.""",
 """'Occupat' is 'seizes', takes before anyone can stop him. 'Custode sepulto' is an ablative absolute, 'the guard buried', a bold word for buried in sleep. 'Evadit ripam' is 'gets beyond the bank', 'evado' used transitively; 'celer' is an adjective doing an adverb's work, 'swiftly'. 'Inremeabilis' is 'not to be retraced' ('inr-' is Greenough's spelling for 'irr-'): the river of the dead is crossed once, one way."""),
(429, 'acerbo;',
 """At once heard were voices, and wailing huge,
and of infants the souls weeping on the threshold first,
whom, of sweet life having no share and from the breast snatched,
carried off a black day and in death drowned bitter;""",
 """At once voices were heard, a great wailing, the souls of babies crying at the very threshold, babes whom a black day stole away, torn from the breast with no share in life's sweetness, and plunged into untimely death;""",
 """A new paragraph. 'Auditae (sunt)': the verb is left short. 'Vagitus' is the crying of a newborn child; 'et' stands second, 'vagitus et ingens' for 'et vagitus ingens'. 'In limine primo' is 'at the very threshold', the first region beyond the river. 'Quos' is masculine, by sense, after the feminine 'animae': it means the infants. 'Exsortes' is 'without a share in', with the genitive 'dulcis vitae' (the Latin Library prints 'exsortis', the same word). 'Atra dies' is 'the black day', the day of death; 'dies' is feminine, as it often is of a fated day. 'Funere… acerbo' is 'in untimely death', 'acerbus' being 'unripe', of fruit. Virgil maps this first part of the underworld by kinds of early death: infants, the falsely condemned, suicides, those destroyed by love, warriors. Line 429 returns at 11.28, for the young Pallas."""),
(430, 'mortis.',
 """these next to, condemned on a false charge to death.""",
 """and next to them those condemned to death on a false charge.""",
 """'Hos iuxta' is 'next to these', the preposition after its object. The verb is left out again. 'Falso… crimine' is 'on a false charge', and 'mortis' is a genitive of the penalty with 'damnati', 'condemned to death', the regular legal construction."""),
(431, 'sedes:',
 """Nor indeed these without lot given, without judge, the seats:""",
 """Yet these places are not assigned without the drawing of lots, or without a judge:""",
 """'Hae… sedes' frames the line, 'these dwellings', with 'datae (sunt)', 'are assigned'. 'Nec vero' is 'nor in truth'. 'Sorte' is the lot by which a Roman jury was drawn: Virgil now turns the underworld into a Roman court. The colon introduces the court itself."""),
(433, 'discit.',
 """the inquisitor Minos the urn shakes; he of the silent
both an assembly summons and their lives and charges learns.""",
 """Minos presides over the inquiry and shakes the urn; he calls together a court of the silent dead, and learns their lives and the charges against them.""",
 """'Quaesitor' is the Roman term for the president of a criminal court (a 'quaestio'), and 'urnam movet', 'shakes the urn', is how the names were drawn by lot. Minos, king of Crete and son of Jupiter, judges the dead: in Odyssey 11 (568–571) Odysseus sees him with a golden sceptre giving judgment among them. 'Silentum' is the genitive plural of the participle 'silens', 'of the silent ones', the dead. 'Concilium' is an assembly; the Latin Library prints 'consilium', the bench of advisers a Roman magistrate sat with, which makes Minos a judge with assessors rather than one summoning the dead together. 'Conciliumque… vitasque' is '-que… -que' again, 'both… and'."""),
(436, 'animas.',
 """Next then hold, in sorrow, the places those who for themselves death,
guiltless, brought forth by their hand, and the light loathing
flung away their lives.""",
 """The next places belong to the sorrowing ones who, guilty of no crime, brought death on themselves by their own hand, and, hating the light, flung away their lives.""",
 """'Proxuma' is Greenough's old spelling of 'proxima' (the Latin Library's), like 'maxumus'. 'Deinde' is scanned as two syllables. 'Peperere' and 'proiecere' are '-ere' perfects for '-erunt' (you have met the form constantly). 'Letum… peperere' is 'brought forth death', a strong verb, 'pario', 'give birth to'. 'Insontes' is 'innocent': they did no crime, and their only fault is the act itself. 'Manu' is 'by their own hand'. 'Perosi' is 'utterly hating', a perfect participle with present sense. These are the suicides."""),
(437, 'labores!',
 """How they would wish, in the air on high,
now both poverty and hard to endure toils!""",
 """How gladly now would they bear poverty and harsh toil in the air above!""",
 """'Quam vellent' is 'how they would wish', exclamatory, the imperfect subjunctive of an unreal wish in present time. 'Aethere in alto' is 'in the upper air', the world of the living. 'Et… et' is 'both… and'. The wish recalls Achilles in Odyssey 11 (489–491), who would rather work the land as hired labourer for a poor man than be king over all the dead."""),
(439, 'coërcet.',
 """Divine law stands in the way, and the grim marsh of unlovely water
binds them, and nine times Styx poured between confines them.""",
 """Heaven's law forbids it: the dismal marsh with its loveless water holds them fast, and Styx, winding nine times between, keeps them penned.""",
 """'Fas' is divine law, what heaven permits; here it bars the way back. 'Inamabilis undae' is a genitive of description, 'of unlovely water'. 'Alligat' is 'binds'. 'Noviens' is Greenough's old spelling of 'novies', 'nine times', and the two dots in 'coërcet' mark that 'co-er-' are separate syllables. 'Interfusa' is 'poured between': the Styx coils nine times between them and the world. In Hesiod (Theogony 790–791) Ocean winds nine times round the earth and the Styx is a tenth stream of it. Lines 438–439 almost repeat Virgil's Georgics (4.479–480), of the dead who heard Orpheus."""),
(441, 'dicunt.',
 """Not far from here, into every part spread, are shown
the Mourning Fields: so them by name they call.""",
 """Not far from here, stretching away on every side, the Fields of Mourning come into view: that is the name they go by.""",
 """A new paragraph. 'Monstrantur' is 'are shown', pointed out by the Sibyl, or simply come into view. 'Partem… in omnem' is 'in every direction', the preposition set between adjective and noun. 'Lugentes campi' is 'the mourning fields': the fields themselves are said to mourn, for the sorrow of those who live there. 'Sic illos nomine dicunt' is 'so they call them by name', with an indefinite 'they': Virgil vouching for a name he did not invent."""),
(444, 'tegit;',
 """Here those whom hard love with cruel wasting has eaten away,
secluded hide paths, and a myrtle round about
wood covers;""",
 """Here those whom harsh love has consumed with its cruel wasting lie hidden in secluded paths, screened by an encircling grove of myrtle;""",
 """'Quos' is the object of 'celant' and 'tegit' as well as of 'peredit'; the antecedent 'eos' is left out. 'Tabe' is 'wasting', the slow consumption of love-sickness, and 'peredit' is 'has eaten through'. 'Secreti… calles' is 'secluded paths'. 'Myrtea… silva' is 'a myrtle wood': the myrtle is Venus's tree. 'Circum' is an adverb, 'round about'."""),
(444, 'relinquunt.',
 """their cares not in death itself leave them.""",
 """not even in death do their sorrows let them go.""",
 """'Curae', 'cares', is the regular word in love-poetry for the pains of love. 'Relinquunt' has 'eos' understood, 'leave them'. 'Ipsa in morte' is 'in death itself', 'even in death'."""),
(447, 'Pasiphaën;',
 """In these Phaedra and Procris places, and sorrowful Eriphyle,
of her cruel son showing the wounds, he sees,
and Evadne and Pasiphaë;""",
 """In this region he sees Phaedra and Procris, and grieving Eriphyle, showing the wounds her cruel son dealt her, and Evadne and Pasiphaë;""",
 """'His… locis' is 'in these places', framing the line. A catalogue of famous women, as in Odyssey 11 (225–332), where they come up one by one to Odysseus; Phaedra, Procris and Eriphyle are all in Homer's list (321–326). Phaedra, wife of Theseus, fell in love with her stepson Hippolytus and, rejected, hanged herself. Procris was killed by her husband Cephalus's javelin when in jealousy she spied on him hunting. Eriphyle, bribed with a necklace, sent her husband Amphiaraus to his death in the war against Thebes, and was killed for it by her son Alcmaeon: 'crudelis nati… volnera' are the wounds he gave her ('volnera' is Greenough's spelling of 'vulnera'). Evadne threw herself onto the pyre of her husband Capaneus; Pasiphaë, wife of Minos, conceived the Minotaur by her monstrous passion for a bull. 'Eriphylen' and 'Evadnen' are Greek accusatives in '-en'; the two dots in 'Pasiphaën' (the Latin Library 'Pasiphaen') mark the 'e' as a syllable of its own. The subject of 'cernit' is Aeneas."""),
(449, 'figuram.',
 """with these Laodamia
goes as companion, and once a young man, now a woman, Caeneus,
again into her old by fate turned back shape.""",
 """Laodamia walks with them, and Caeneus, once a young man and now a woman, turned back by fate into her first shape.""",
 """'His… it comes' is 'goes as a companion to these', 'his' a dative. Laodamia's husband Protesilaus was the first Greek killed at Troy; the gods let him come back to her for three hours, and when he went down again she died with him. Caeneus was born a girl, Caenis, changed into a man by Neptune and made invulnerable; in death she has her first form again. The grammar makes the change: 'Caeneus', a man's name, takes the feminine 'revoluta'. 'Rursus et' is 'et rursus', with 'et' standing second. 'Laodamia' ends with '-mia' read as one syllable (-mya); 'Caeneus' ends in the Greek diphthong '-eus', one syllable."""),
(451, 'magna;',
 """Among whom, the Phoenician, fresh from her wound, Dido
was wandering in the wood great;""",
 """Among them Phoenician Dido, her wound still fresh, was wandering in the great forest;""",
 """A new paragraph. 'Inter quas' is a connecting relative, 'among these (women)'. 'Phoenissa' is 'the Phoenician woman', Dido of Tyre, and her name is held back to the end of the line. 'Recens a volnere' is 'fresh from her wound', the sword of Book IV: she has been dead only a few weeks. 'Errabat' is the imperfect of a scene going on. 'Silva in magna' sets the preposition between noun and adjective."""),
(455, 'est:',
 """whom the Trojan hero,
as soon as near he stood and recognised through the shadows,
dim, as at the month's beginning one who rising
either sees, or thinks he has seen, through clouds the moon,
let fall tears, and with sweet addressed her love:""",
 """and as soon as the Trojan hero stood close by and knew her, dim in the shadows, as a man sees the new moon rising through clouds at the month's beginning, or thinks he has seen it, he let his tears fall and spoke to her in tender love:""",
 """'Quam' (Dido) is the object of 'adgnovit', Greenough's spelling of 'agnovit' (the Latin Library's). 'Ut primum' is 'as soon as'. 'Obscuram' is predicative, 'dim'. The simile: 'qualem… lunam' is 'such as is the moon which a man sees, or thinks he has seen, rising through clouds at the start of the month', the thin new moon; the relative 'qui' (the man) is put before its clause, and 'primo… mense' is an ablative of time. The image comes from Apollonius of Rhodes (Argonautica 4.1477–1480), where Lynceus thinks he glimpses Heracles far off, like a new moon through cloud. 'Demisit lacrimas' is 'let fall tears'. 'Adfatus… est' is the perfect of the deponent 'adfor', 'address', and 'dulci… amore' an ablative of manner."""),
(457, 'secutam?',
 """“Unhappy Dido, true to me the message then
had come, that you were dead, and with the sword had followed the end?""",
 """“Unhappy Dido, so the news that reached me was true, that you were gone, that you had sought your end with the sword?""",
 """A new paragraph. The opening mark begins Aeneas's speech, which runs to 466. 'Infelix' is Dido's word all through Book IV. 'Ergo' is 'then', 'so it was'. 'Nuntius… venerat' is 'a message had come', followed by an accusative and infinitive with 'te' and 'esse' left out: '(te) exstinctam (esse)', 'that you were dead'. Virgil never says how the news reached him; at the opening of Book V he only saw the glow of the pyre from the sea and guessed. 'Extrema' is 'the last things', death; 'secutam' is from the deponent 'sequor', and 'ferro' is 'with the sword'."""),
(458, 'fui?',
 """Of your death, alas, to you the cause was I?""",
 """Was I, alas, the cause of your death?""",
 """'Funeris' is properly 'of the funeral', here 'of your death'; 'tibi' is a dative of reference. 'Heu' is the cry 'alas'."""),
(460, 'cessi.',
 """By the stars I swear,
by those above, and if any faith under the earth deepest is,
unwilling, queen, from your shore I departed.""",
 """I swear by the stars, by the gods above, by whatever is held sacred in the depths of the earth: it was against my will, my queen, that I went from your shores.""",
 """'Per' is the preposition of swearing, 'by'. 'Superos' is 'the gods above'. 'Si qua fides… est' is 'if there is any faith', 'qua' the indefinite after 'si': whatever is sworn by under the earth, where he now stands. 'Tellure sub ima' is 'beneath the lowest earth'. Line 460 adapts Catullus (66.39), where the lock of Queen Berenice's hair, set among the stars, tells her 'invita, o regina, tuo de vertice cessi', 'unwilling, queen, I left your head': a playful line of court poetry made tragic. 'Cessi' is 'I withdrew'."""),
(464, 'dolorem.',
 """But me the commands of the gods, which now through these to go shades,
through places rough with decay, compel, and night profound,
with their authority drove; nor to believe was I able
that this so great on you I by departing would bring grief.""",
 """But the commands of the gods, which force me now to pass through these shadows, through places rank with decay and bottomless night, drove me with their authority; and I could not believe that by going I would bring such grief upon you.""",
 """'Deum' is the old genitive plural in '-um', 'of the gods'. 'Quae… cogunt (me) ire' is 'which compel (me) to go'. 'Senta situ' is 'rough with neglect', 'situs' being the mould and squalor of disuse. 'Egere' is the '-ere' perfect for 'egerunt', 'drove', and 'imperiis… suis' is an ablative of means. 'Quivi' is the perfect of 'queo', 'I was able'. 'Hunc tantum… dolorem' frames the line, 'this so great grief'; 'me… ferre' is an accusative and infinitive, and 'discessu' an ablative of means, 'by my departure'. This was his defence in Book IV (IV.340–361): the gods sent him to Italy, and he did not go of his own will."""),
(465, 'nostro.',
 """Stay your step, and yourself from sight do not withdraw our.""",
 """Stop, and do not take yourself out of my sight.""",
 """'Siste gradum' is 'halt your step'. 'Ne subtrahe' is 'ne' with the imperative, an old and poetic form of prohibition (prose says 'noli subtrahere'). 'Aspectu… nostro' is an ablative of separation, 'from our sight', with 'nostro' the plural for 'my'."""),
(466, 'fugis?',
 """Whom do you flee?""",
 """Who is it you are running from?""",
 """A sudden cry of two words. In Book IV (IV.314) it was Dido who asked 'Mene fugis?', 'Is it me you are running from?'; now the roles are reversed."""),
(466, 'est.”',
 """The last by fate, that I speak to you, this is.”""",
 """This is the last time fate will let me speak to you.”""",
 """'Hoc est extremum… quod te adloquor' is 'this is the last (time) that I address you', 'quod' being 'the fact that'. 'Fato' is 'by fate', an ablative of cause: it is fated to be the last. 'Adloquor' is Greenough's spelling of 'alloquor'; 'te adloquor' elides. The closing mark ends Aeneas's speech."""),
(468, 'ciebat.',
 """With such Aeneas, her burning and grimly glaring
tried to soothe, with words, spirit, and tears kept stirring.""",
 """With such words Aeneas tried to soften her blazing, fiercely glaring spirit, and his own tears kept welling.""",
 """A new paragraph. 'Talibus… dictis' frames the clause, 'with such words'. 'Ardentem et torva tuentem' go with 'animum': her spirit 'burns' and 'glares grimly'. 'Torva' is a neuter plural used as an adverb, an internal accusative of Greek type. 'Lenibat' is the old imperfect for 'leniebat', and conative, 'tried to soothe'. 'Lacrimas ciebat' is 'kept calling up tears', his own, though some have taken them as hers."""),
(471, 'cautes.',
 """She, on the ground fixed, her eyes, turned away, kept,
nor more by his begun in face speech is she moved
than if hard flint or should stand Marpessian rock.""",
 """Turned away, she kept her eyes fixed on the ground, and her face was no more moved by the words he had begun than if she stood there hard flint or a crag of Marpessian marble.""",
 """'Solo' is 'on the ground', dative or ablative with 'fixos'. 'Aversa' is 'turned away'. 'Incepto… sermone' is 'by the speech he had begun', an ablative of means. 'Voltum' (Greenough's spelling of 'vultum') is an accusative of respect, 'moved in her face'. 'Silex', 'flint', is feminine here. 'Marpesia cautes' is a crag of Marpessus, the mountain on Paros where the famous marble was quarried. Her silence is modelled on Odyssey 11 (543–564), where the shade of Ajax, still angry with Odysseus over the arms of Achilles, will not answer him and walks away into Erebus. And Dido is now as unmoved as Aeneas was in Book IV, standing firm like an oak (IV.441–449), the man she said was born of hard rock (IV.366–367)."""),
(474, 'amorem.',
 """At last she snatched herself away, and, hostile, fled back
into the grove shadowy, where her husband of old to her
answers her cares and matches, Sychaeus, her love.""",
 """At last she tore herself away and fled, still his enemy, into the shadowy grove where Sychaeus, her husband of old, answers her sorrows and gives her love for love.""",
 """The print has 'tandem' with a small letter after the full stop at the end of 471, a misprint for 'Tandem', corrected here. t keeps the print, because t must match the pinned source; l and i begin with a capital. 'Corripuit sese' is 'snatched herself up', 'tore herself away'. 'Inimica' is predicative, 'as an enemy'. 'Ubi' is put after 'coniunx'. 'Coniunx… pristinus' is 'her former husband', Sychaeus, murdered by her brother Pygmalion (1.343–356), to whose memory she had sworn to stay faithful (IV.24–29). 'Illi' is a dative with 'respondet', 'answers her cares', and 'aequat… amorem' is 'matches her love'."""),
(476, 'euntem.',
 """Nor less Aeneas, by her fate shaken unjust,
follows her with tears far, and pities her going.""",
 """Aeneas, no less shaken by her cruel fate, followed her a long way with his tears and pitied her as she went.""",
 """'Nec minus' is 'no less', that is, all the same. 'Casu… iniquo' is 'by her unjust fortune', framing 'concussus', 'shaken' (the Latin Library prints 'percussus', 'struck', to much the same effect). 'Prosequitur lacrimis' is 'escorts with tears', the word for seeing someone off on a journey. 'Longe' is 'far', as far as his eyes can follow. 'Miseratur euntem' is 'pities her as she goes'."""),
(477, 'iter.',
 """Then the granted he labours along way.""",
 """Then he pressed on along the road allotted him.""",
 """A new paragraph. 'Datum… iter' is 'the given road', the way granted him by fate. 'Molitur' is 'labours at', 'toils along': the deponent 'molior' always carries effort."""),
(478, 'frequentant.',
 """And now the fields they were reaching,
the farthest, which those in war famous, apart, throng.""",
 """And now they were coming into the farthest fields, the secluded haunt of men renowned in war.""",
 """'Tenebant' is 'were reaching', 'were making for', imperfect. 'Ultima' is 'the farthest', the last region before the road divides (540). 'Bello clari' is 'men famous in war', with an ablative of respect. 'Secreta' goes with 'arva', 'set apart', or is used as an adverb, 'in seclusion'. 'Frequentant' is 'throng', 'haunt'."""),
(480, 'imago;',
 """Here to him comes to meet Tydeus, here famed in arms
Parthenopaeus, and of Adrastus pale the image;""",
 """Here Tydeus comes to meet him, here Parthenopaeus, famed in arms, and the ghost of pallid Adrastus;""",
 """'Illi' is a dative with 'occurrit', 'meets him'. 'Hic… hic' is anaphora, the repeated word marking off each sight. These are three of the Seven against Thebes, the war of the generation before Troy: Tydeus, father of Diomedes; Parthenopaeus, the young son of Atalanta; and Adrastus, king of Argos, who led the expedition. 'Pallentis' is 'pale', as the dead are. 'Imago' is 'image', 'shade'. 'Tydeus' has two syllables, '-eus' being a Greek diphthong."""),
(485, 'tenentem.',
 """here much wept for among those above, and in war fallen,
the Dardanians, whom he all in long line seeing
groaned, Glaucus and Medon and Thersilochus,
the three sons of Antenor, and to Ceres consecrated Polyphoetes,
and Idaeus, still his chariot, still his arms holding.""",
 """here the Trojans fallen in battle and much lamented in the world above, and he groaned as he saw them all in their long array, Glaucus, Medon and Thersilochus, the three sons of Antenor, Polyphoetes the priest of Ceres, and Idaeus, still holding his chariot, still his arms.""",
 """'Multum fleti ad superos' is 'much wept among those above', the living. 'Caduci' is 'fallen', a rare sense of the word. 'Dardanidae' is 'sons of Dardanus', Trojans. 'Ingemuit' takes the names as its objects, 'groaned over'. 'Longo ordine' is 'in a long line'. Glaucus, Medon and Thersilochus are named together in Homer's list of Trojan allies (Iliad 17.216); Antenor, an elder of Troy, had three sons, Polybus, Agenor and Acamas, who fight side by side in the Iliad (11.59–60); 'tris' is the '-is' accusative plural. Polyphoetes, 'consecrated to Ceres', is known only here; the Latin Library calls him 'Polyboetes'. Idaeus was Priam's herald and driver (Iliad 24). 'Etiam… etiam' is 'still… still': the dead keep what they loved in life, as Virgil shows again at 653–655. 'Glaucumque Medontaque Thersilochumque' is the Homeric line of names strung on '-que'."""),
(486, 'frequentes;',
 """Around stand the souls on the right and the left in crowds;""",
 """The souls crowd round him on right and left;""",
 """The print has 'circumstant' with a small letter after the full stop at the end of 485, a misprint for 'Circumstant', corrected here. t keeps the print, because t must match the pinned source; l and i begin with a capital. 'Dextra laevaque' is '(on) the right (side) and the left', with 'parte' understood. 'Frequentes' is predicative, 'in crowds'."""),
(487, 'est;',
 """nor to have seen him once enough is;""",
 """to have seen him once is not enough;""",
 """'Vidisse' is a perfect infinitive used as the subject of 'satis est'. 'Semel' is 'once'."""),
(488, 'causas.',
 """it pleases them on and on to linger,
and to match step, and of his coming to learn the reasons.""",
 """they love to linger on and on, to walk step by step beside him, and to learn why he has come.""",
 """'Iuvat' is impersonal, 'it delights (them)', with three infinitives. 'Usque' is 'continually'. 'Conferre gradum' is 'to bring step together with', to walk alongside. 'Veniendi' is the genitive of the gerund with 'causas', 'the reasons for coming'."""),
(491, 'metu;',
 """But of the Danaans the chiefs and Agamemnon's phalanxes,
when they saw the man and his gleaming arms through the shadows,
with huge to tremble fear;""",
 """But the Greek chieftains and Agamemnon's battalions, when they saw the man and his arms flashing through the gloom, shook with mighty terror;""",
 """'Danaum' is the genitive plural in '-um', 'of the Danaans', the Greeks. 'Agamemnoniae' is an adjective doing a genitive's work, 'of Agamemnon'. 'Ut' with the perfect indicative is 'when', and 'videre' is the '-ere' perfect for 'viderunt'. 'Trepidare' is a historic infinitive: an infinitive standing for a finite verb in quick narrative, with its subject in the nominative ('proceres… phalanges'). Two more follow, 'vertere' and 'tollere'; watch for the construction. The Greek dead fear the living Trojan they once routed: his flashing armour shows he is alive."""),
(492, 'rates;',
 """some to turn their backs,
as once they made for the ships;""",
 """some turned and fled, as once they had run for their ships;""",
 """'Pars… pars' is 'some… others'. 'Vertere' is a historic infinitive like 'trepidare', not an '-ere' perfect; 'petiere' is the perfect, for 'petierunt'. 'Ceu' is a poetic 'as'. 'Quondam' is 'once', when Hector drove the Greeks back to their ships at Troy (Iliad 15)."""),
(493, 'hiantes.',
 """some to raise a voice,
thin: the shout begun mocks them gaping.""",
 """others raised a feeble cry: the war-shout they began died away in their gaping mouths.""",
 """'Tollere' is the third historic infinitive. 'Exiguam' is 'tiny', 'thin': the voices of the dead are faint, as in Odyssey 24 (5–9), where the shades of the suitors squeak like bats. 'Inceptus clamor' is 'the shout begun', the battle-cry they try to raise. 'Frustratur' is 'disappoints', 'cheats', and 'hiantes' is 'them gaping', open-mouthed (the Latin Library 'hiantis', the same). The last clause follows with no connective."""),
(497, 'nares.',
 """And here Priam's son, mangled in his whole body,
Deiphobus he sees, and torn cruelly as to the face,
the face and both hands, and the temples ravaged, ripped away
the ears, and lopped with dishonouring wound the nostrils.""",
 """And here he saw Priam's son Deiphobus, mangled all over his body, his face cruelly torn, his face and both his hands, his temples stripped where the ears had been ripped away, and his nose cut off by a shameful wound.""",
 """A new paragraph. 'Priamiden' is the Greek accusative of 'Priamides', 'son of Priam'. Deiphobus married Helen after Paris was killed, and died on the night Troy fell; in the Odyssey (8.517–520) Odysseus and Menelaus make first for his house in the sack. 'Laniatum corpore toto' is 'mangled in his whole body', 'corpore' an ablative of respect. 'Lacerum… ora' is 'torn as to the face', the Greek accusative of respect with a participle or adjective of the body (you will meet it often). 'Ora… ora' is repeated across the line-break to hold the eye on the wound. 'Populata… tempora raptis / auribus' is 'his temples ravaged, the ears torn off', 'raptis auribus' an ablative absolute or of means. 'Truncas… nares' is 'his nostrils cropped', and 'inhonesto volnere' 'with a disgraceful wound': cutting off ears, nose and hands was mutilation meant to shame. How it was done he tells in the lines that follow."""),
(499, 'ultro:',
 """Scarcely indeed he knew him, cowering and the dreadful hiding
punishments, and in familiar addresses him words first:""",
 """He hardly knew him, as he cowered and tried to hide the dreadful marks of his torture, and he spoke to him first, in a friend's familiar words:""",
 """'Vix adeo' is 'only just', 'adeo' strengthening 'vix'. 'Adgnovit' is Greenough's spelling of 'agnovit'; 'adeo adgnovit' elides. 'Pavitantem' is the frequentative of 'paveo', 'trembling', 'cowering'. 'Dira… supplicia' is 'dreadful punishments', the mutilations, run over the line-end. 'Et' is 'ac' in the Latin Library, no difference. 'Compellat' is 'addresses'. 'Notis… vocibus' is 'with familiar words', the speech of an old friend. 'Ultro' is 'of his own accord', speaking first, since Deiphobus is hiding. The colon opens Aeneas's words."""),
(501, 'poenas?',
 """“Deiphobus, mighty in arms, offspring from the high blood of Teucer,
who such cruel chose to exact penalties?""",
 """“Deiphobus, strong warrior, scion of Teucer's lofty line, who chose to take a vengeance so cruel?""",
 """The opening mark begins Aeneas's speech, which runs to 508. 'Deiphobe' is the vocative, with 'Dei-' read as one syllable and the final 'e' elided before 'armipotens'. 'Armipotens', 'powerful in arms', is a compound adjective of the old epic kind. 'Genus' is in apposition, 'offspring', 'scion'. Teucer was the first king of the Trojan land, an ancestor of Priam's line; 'Teucri' ends with the Greek diphthong 'eu', one syllable. 'Optavit' is 'chose'. 'Sumere poenas' is 'to exact a penalty', of the avenger. 'Crudeles' is 'crudelis' in the Latin Library, the same word."""),
(502, 'licuit?',
 """To whom so much in your case was allowed?""",
 """Who was given such licence over you?""",
 """'Cui… licuit' is 'to whom was it permitted', the impersonal 'licet' with a dative. 'Tantum de te' is 'so much in your case', 'at your expense'."""),
(504, 'acervum.',
 """To me the report, on the last
night, brought that you, weary from the vast slaughter of Pelasgians,
had fallen upon of the confused carnage the heap.""",
 """The word that reached me told that on that last night, worn out from killing Greeks in vast numbers, you had sunk down on a heap of mingled slain.""",
 """'Fama… tulit' is 'report carried (word)', followed by the accusative and infinitive 'te… procubuisse', 'that you had fallen forward'. 'Suprema… nocte' is 'on the last night', the night Troy fell. 'Fessum vasta… caede' is 'tired out by vast slaughter', an ablative of cause, and 'Pelasgum' is the genitive plural in '-um' of 'Pelasgi', an old name for the Greeks. 'Super' governs 'acervum', 'upon the heap'. 'Confusae stragis' is 'of mingled carnage', bodies Greek and Trojan together."""),
(506, 'vocavi.',
 """Then I myself a mound on the Rhoetean shore, empty,
set up, and with a great the Manes three times voice called.""",
 """Then I myself raised an empty mound on the Rhoetean shore and three times called aloud upon your spirit.""",
 """'Egomet' is an emphatic 'I myself'. 'Tumulum… inanem' is 'an empty tomb', a cenotaph, built for the dead whose body could not be found, so that the soul should still have its resting-place; Andromache keeps one for Hector (3.303–305). 'Rhoeteo litore' is an ablative of place with no preposition (the Latin Library adds 'in'): Rhoeteum is a headland on the coast by Troy. 'Manes' is the spirit of the dead man. Calling the dead three times by name was a rite of burial; in the Odyssey (9.65) Odysseus's men call three times on each comrade lost on the shore before they sail. 'Magna… voce' wraps round 'Manes ter'."""),
(507, 'servant;',
 """Your name and arms the place keep;""",
 """Your name and your armour mark the place;""",
 """'Nomen et arma' are the inscription on the tomb and the arms set up on it, standing in for the man. Compare the place that will keep Palinurus's name (381)."""),
(508, 'terra.”',
 """you, friend, I could not
see, and, departing, in your native lay to rest earth.”""",
 """but you, my friend, I could not find, nor lay you in your native earth as I left it.”""",
 """'Te' is emphatic, set against 'nomen et arma' with no 'but'; 'te, amice' elides. 'Nequivi' is the perfect of 'nequeo', 'I was unable'. 'Conspicere' is 'catch sight of'. 'Patria… terra' is an ablative of place, 'in your native land', framing the line-end, and 'decedens' is 'as I departed', leaving Troy. 'Ponere' is 'to lay to rest', to bury. The closing mark ends Aeneas's speech; Deiphobus answers in the next part."""),
]
P = A.part('aeneid-044'); L = A.lines_of(P); paras = {l['n'] for l in L if l['p']}
cuts = A.cut(P, [(u[0], u[1]) for u in U])
sents = []; prev_end_line = None
for (t, ln), (_, _t, l, i, n) in zip(cuts, U):
    u = {'t': t, 'l': l, 'i': i, 'n': n}
    if prev_end_line != ln and ln in paras: u['p'] = True
    u['v'] = True; u['ln'] = ln; sents.append(u)
    prev_end_line = ln + t.count('\n')
    if t.count('\n') != l.count('\n'): print('LINE COUNT', ln, repr(t[:30]), t.count('\n'), l.count('\n'))
    if t.count('\n') > 4: print('TOO LONG', ln)
    if '\n' in i: print('NEWLINE IN i', ln)
A.jdump({'title': TITLE, 'titleEn': TITLE_EN, 'part': PART, 'about': ABOUT, 'sentences': sents}, os.path.join(HERE, 'units.json'))
print(len(sents), 'units')
